<section class="page-head"><div><span class="eyebrow">ORDER ADMINISTRATION</span><h1><?= e(\App\Services\OrderReference::display($order)) ?></h1><p><?= e(ucfirst($order['status'])) ?> · <?= e($order['created_at']) ?></p></div><a class="btn btn-secondary" href="<?= e(url('/admin/orders')) ?>">All orders</a></section>
<section class="panel admin-order-contact"><h2>Contact and delivery</h2><p><?= e($order['recipient_name_snapshot']??'Not recorded') ?></p><p><?= e($order['contact_email_snapshot']??'') ?> · <?= e($order['contact_no_snapshot']??'') ?></p><p><?= e($order['delivery_address_snapshot']) ?></p><p><?= $order['payment_method']==='cod'?'Cash on delivery':'Manual payment' ?></p></section>
<div class="order-table-wrap"><table><thead><tr><th scope="col">Item</th><th scope="col">Quantity</th><th scope="col">Unit price</th></tr></thead><tbody>
<?php foreach($order['items'] as $item): ?><tr><td><?= e($item['product_name_snapshot']) ?></td><td><?= (int)$item['quantity'] ?></td><td>₱<?= e(number_format((float)$item['unit_price_snapshot'],2)) ?></td></tr><?php endforeach; ?>
</tbody><tfoot><?php if($order['delivery']): ?><tr><th colspan="2">Shipping</th><td>₱<?= e(number_format((float)$order['delivery']['shipping_fee'],2)) ?></td></tr><?php endif; ?><tr><th colspan="2">Order total</th><td>₱<?= e(number_format((float)$order['total'],2)) ?></td></tr></tfoot></table></div>
<section class="panel"><h2>Recorded updates</h2><?php if(!$order['events']): ?><p>No earlier status events were recorded.</p><?php else: ?><ol><?php foreach($order['events'] as $event): ?><li><?= e(ucfirst($event['to_status'])) ?> · <time><?= e($event['created_at']) ?></time></li><?php endforeach; ?></ol><?php endif; ?></section>
